using System;

namespace object_oriented_game_programming
{
    class Enemy
    {
        public string name;
        public int expYield;
        public int hp;

        public Enemy()
        {
            name = "Default Enemy Name";
            hp = 999;
            expYield = 99;
        }

        public Enemy(string _name, int _expYield, int _hp)
        {
            name = _name;
            expYield = _expYield;
            hp = _hp;
        }

        public void Attack(string target, int atkCount)
        {
            Console.WriteLine($"{name} Attack the {target} for {atkCount} times and and gain some exp, +{2*atkCount} EXP\n");
            expYield += 2*atkCount;
            GetStats();
        }
        public void Move()
        {
            Console.WriteLine($"{name} Moved and tripped into a barb wire, -1 HP\n");
            hp--;
            GetStats();
        }
        public void GetStats()
        {
            Console.WriteLine("======STATS======");
            Console.WriteLine($"Name: {name}");
            Console.WriteLine($"HP: {hp}");
            Console.WriteLine($"EXP: {expYield}");
            Console.WriteLine("=================\n");
        }
    }
    internal class Program
    {
        static void Main(string[] args)
        {
            Enemy enemy1 = new Enemy();
            Enemy enemy2 = new Enemy("Asep",55,502);

            enemy1.GetStats();
            enemy2.GetStats();

            enemy1.name = "Aegis";
            enemy1.hp = 100;

            enemy1.GetStats();

            enemy1.Attack("Goblin",5);
            enemy1.Move();
        }
    }
}
